import {fields,days} from './calculations.js';
export const emptyPreferences=()=>({goals:[],reminder:null});
export const validDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;
export const today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
export function validContext(c){return c==null||typeof c==='object'&&!Array.isArray(c)&&Object.keys(c).every(k=>['time','training','conditions'].includes(k))&&(c.time==null||c.time===''||/^([01]\d|2[0-3]):[0-5]\d$/.test(c.time))&&(c.training==null||['','rest','before','after'].includes(c.training))&&(c.conditions==null||typeof c.conditions==='string'&&c.conditions.length<=300);}
export function validPreferences(p){return !!(p&&typeof p==='object'&&!Array.isArray(p)&&Object.keys(p).every(k=>['goals','reminder'].includes(k))&&Array.isArray(p.goals)&&p.goals.length<=6&&new Set(p.goals.map(g=>g?.id)).size===p.goals.length&&p.goals.every(g=>g&&/^[-\w]{1,100}$/.test(g.id)&&Object.hasOwn(fields,g.metric)&&Number.isFinite(g.target)&&g.target>0&&(g.metric!=='fat'||g.target<100)&&validDate(g.date)&&validDate(g.startDate)&&g.date>=g.startDate&&(g.baseline===null||Number.isFinite(g.baseline)&&g.baseline>0))&&(p.reminder===null||validDate(p.reminder)));}
export function goalStatus(goal,records){const latest=[...records].filter(r=>r.date>=goal.startDate&&Number.isFinite(r[goal.metric])).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);if(!latest)return null;const value=latest[goal.metric],distance=goal.target-value,span=goal.target-goal.baseline;return {value,date:latest.date,distance,progress:goal.baseline===null?null:span===0?(value===goal.target?100:0):Math.max(0,Math.min(100,(value-goal.baseline)/span*100))};}
export function unusualChanges(record,records){const previous=[...records].filter(r=>r.id!==record.id&&r.date<=record.date).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);if(!previous)return [];return Object.keys(fields).filter(k=>Number.isFinite(record[k])&&Number.isFinite(previous[k])&&previous[k]>0&&Math.abs(record[k]-previous[k])/previous[k]>.2).map(k=>({key:k,before:previous[k],after:record[k],days:days(previous.date,record.date)}));}
export const photoName=/^\d{4}-\d{2}-\d{2}_(front|side|back)_[a-f0-9-]{36}\.jpg$/;
export function validPhoto(p){return !!(p&&photoName.test(p.name)&&validDate(p.name.slice(0,10))&&typeof p.data==='string'&&p.data.length<=1400000&&/^data:image\/jpeg;base64,\/9j\/[A-Za-z0-9+/=]+$/.test(p.data));}
